    for p in pats:
        ms = list(re.finditer(p, doc, flags=re.I))
        print(f"--- /{p}/ : {len(ms)} hits")
        for m in ms[:maxn]:
            s = max(0, m.start()-w); e = min(len(doc), m.end()+w)
            print("   …", doc[s:e].replace("\n"," "), "…\n")

